// Strategy: pre-cache app shell; cache audio on demand as it is played.
const CACHE_PREFIX = 'flippy2-';
const CACHE_SHELL  = 'flippy2-shell-v25.4';
const CACHE_AUDIO  = 'flippy2-audio';
const SHELL_FILES = [
  "index.html",
  "manifest.json",
  "icons/icon-192.png",
  "icons/icon-512.png"
];

// Install: pre-cache the app shell only (fast, small)
self.addEventListener('install', e => {
  e.waitUntil(
    caches.open(CACHE_SHELL).then(cache => cache.addAll(SHELL_FILES))
  );
  self.skipWaiting();
});

// Activate: delete only THIS site's older caches.
// caches.keys() is origin-wide and this origin also serves the other Flippy
// site, so the CACHE_PREFIX filter is what protects its downloaded audio.
// Older releases kept audio in a per-version cache ("<prefix>audio-v23.4").
// Copy those entries into the fixed audio cache BEFORE sweeping so a release
// never throws away downloaded audio.
self.addEventListener('activate', e => {
  const keep = [CACHE_SHELL, CACHE_AUDIO];
  e.waitUntil((async () => {
    const keys = await caches.keys();
    const legacy = keys.filter(k => k.startsWith(CACHE_PREFIX + 'audio-v'));
    if (legacy.length) {
      const dest = await caches.open(CACHE_AUDIO);
      for (const k of legacy) {
        const src = await caches.open(k);
        for (const req of await src.keys()) {
          if (!(await dest.match(req))) {
            const res = await src.match(req);
            if (res) await dest.put(req, res);
          }
        }
      }
    }
    await Promise.all(
      keys.filter(k => k.startsWith(CACHE_PREFIX) && !keep.includes(k))
          .map(k => caches.delete(k))
    );
    await self.clients.claim();
  })());
});

// Fetch: audio is cache-first (big, never changes). The app shell is
// network-first so a new release shows up on the next open; the cache is the
// offline fallback.
self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  const url = new URL(e.request.url);
  const isAudio = url.pathname.includes('/audio/') || url.pathname.endsWith('.mp3');
  if (isAudio) {
    e.respondWith(
      caches.match(e.request).then(cached => {
        if (cached) return cached;
        return fetch(e.request).then(response => {
          if (response.ok && response.type !== 'opaque') {
            caches.open(CACHE_AUDIO).then(c => c.put(e.request, response.clone()));
          }
          return response;
        });
      })
    );
    return;
  }
  e.respondWith(
    fetch(e.request).then(response => {
      if (response.ok && response.type !== 'opaque') {
        caches.open(CACHE_SHELL).then(c => c.put(e.request, response.clone()));
      }
      return response;
    }).catch(() => caches.match(e.request, { ignoreSearch: true }))
  );
});
